import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATUSES = ['신청', '마감', '마감취소', '승인', '승인취소'];

function transition(idText: string | undefined, from: string, to: string) {
  if (typeof idText !== 'string' || !/^\d+$/.test(idText)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '실행예산 ID가 올바르지 않습니다.');
  }
  return transaction(async (db) => {
    const found = await db.query(
      'SELECT status AS "status" FROM exec_budget WHERE exec_budget_id = CAST(:id AS bigint) FOR UPDATE',
      { id: idText },
    );
    if (found.length === 0) {
      throw new ApiError(404, 'EXEC_BUDGET_NOT_FOUND', '실행예산을 찾을 수 없습니다.');
    }
    const current = found[0]['status'];
    if (current !== from) {
      throw new ApiError(
        409,
        'EXEC_BUDGET_STATUS_CONFLICT',
        '현재 상태가 ' + String(current) + '이라 처리할 수 없습니다. ' + from + ' 상태에서만 처리할 수 있습니다.',
      );
    }
    const rows = await db.query(
      'UPDATE exec_budget SET status = :to, updated_at = now() WHERE exec_budget_id = CAST(:id AS bigint) RETURNING status AS "status"',
      { id: idText, to },
    );
    return rows[0];
  });
}

@Controller('api/v1')
export class FnSfr00306Controller {
  @Get('/exec-budgets')
  async listExecBudgets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const statusRaw = query['status'];
    let status: string | null = null;
    if (statusRaw !== undefined && statusRaw !== null && statusRaw !== '') {
      if (typeof statusRaw !== 'string' || !STATUSES.includes(statusRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
      }
      status = statusRaw;
    }
    const page = query['page'] ? Number(query['page']) : 0;
    const size = query['size'] ? Number(query['size']) : 20;
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const limit = Math.min(size, 200);
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT exec_budget_id AS "execBudgetId", budget_month AS "budgetMonth", amount AS "amount", status AS "status" ' +
          'FROM exec_budget WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar)) ' +
          'ORDER BY exec_budget_id DESC LIMIT :limit OFFSET :offset',
        { status, limit, offset: page * limit },
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM exec_budget WHERE (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))',
        { status },
      );
      return { items, page, size: limit, total: Number(counted[0]['total']) };
    });
  }

  @Post('/exec-budgets/:execBudgetId/close')
  @HttpCode(200)
  async closeExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transition(req.params['execBudgetId'], '신청', '마감');
  }

  @Post('/exec-budgets/:execBudgetId/cancel-close')
  @HttpCode(200)
  async cancelCloseExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transition(req.params['execBudgetId'], '마감', '마감취소');
  }

  @Post('/exec-budgets/:execBudgetId/approve')
  @HttpCode(200)
  async approveExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transition(req.params['execBudgetId'], '마감', '승인');
  }

  @Post('/exec-budgets/:execBudgetId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return transition(req.params['execBudgetId'], '승인', '승인취소');
  }
}

