import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

interface Action {
  key: string;
  label: string;
  path: string;
  from: string;
  danger?: boolean;
}

const ACTIONS: Action[] = [
  { key: 'close', label: '마감', path: 'close', from: '신청' },
  { key: 'approve', label: '승인', path: 'approve', from: '마감' },
  { key: 'cancel-close', label: '마감취소', path: 'cancel-close', from: '마감', danger: true },
  { key: 'cancel-approval', label: '승인취소', path: 'cancel-approval', from: '승인', danger: true },
];

export default function FnSfr00306Page({ role, notify }: PageProps) {
  const [statusDraft, setStatusDraft] = useState('');
  const [status, setStatus] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<{ row: Row; action: Action } | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/exec-budgets', role, undefined, { status, page: pageNo, size: 20 }),
    [status, pageNo],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/exec-budgets', role, undefined, { status: '신청', page: 0, size: 1 }),
    [],
  );
  const closed = useData<Page>(
    () => call<Page>('GET', '/exec-budgets', role, undefined, { status: '마감', page: 0, size: 1 }),
    [],
  );

  const reloadAll = () => {
    list.reload();
    waiting.reload();
    closed.reload();
  };

  const search = () => {
    setPageNo(0);
    setStatus(statusDraft);
  };

  const reset = () => {
    setStatusDraft('');
    setStatus('');
    setPageNo(0);
  };

  const run = async () => {
    if (!target) return;
    await call('POST', '/exec-budgets/' + String(target.row['execBudgetId']) + '/' + target.action.path, role, {});
    notify('실행예산을 ' + target.action.label + ' 처리했습니다.');
    setTarget(null);
    reloadAll();
  };

  const columns = [
    { key: 'execBudgetId', label: '실행예산 ID' },
    { key: 'budgetMonth', label: '편성 월', render: (r: Row) => String(r['budgetMonth']) + '월' },
    { key: 'amount', label: '실행예산 금액', render: (r: Row) => <Num value={r['amount']} /> },
    { key: 'status', label: '상태', render: (r: Row) => <Badge value={r['status']} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          {ACTIONS.filter((a) => a.from === r['status']).map((a) => (
            <button key={a.key} type="button" onClick={() => setTarget({ row: r, action: a })}>
              {a.label}
            </button>
          ))}
        </span>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['마감 대기(신청)', <Num value={waiting.data ? waiting.data.total : 0} />],
            ['승인 대기(마감)', <Num value={closed.data ? closed.data.total : 0} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>실행예산</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="상태">
            <Select value={statusDraft} onChange={setStatusDraft} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : 0} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={list.data ? list.data.items : []} empty="실행예산이 없습니다." />
        {list.data ? (
          <Pager page={list.data.page} size={list.data.size} total={list.data.total} onPage={setPageNo} />
        ) : null}
      </section>
      {target ? (
        <Drawer title={'실행예산 ' + target.action.label} onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['실행예산 ID', String(target.row['execBudgetId'])],
              ['편성 월', String(target.row['budgetMonth']) + '월'],
              ['실행예산 금액', <Num value={target.row['amount']} />],
              ['상태', <Badge value={target.row['status']} />],
            ]}
          />
          <Form
            onSubmit={run}
            submit={target.action.label}
            danger={target.action.danger}
            note={'선택한 실행예산을 ' + target.action.label + ' 처리합니다.'}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
